//! Vectors for RNG (`blocks/iop/rng.h`), generated by `scripts/cpp_vectors/rng_vectors.cpp`:
//! the shape's faults, the lookup's public inputs, the multiplicities' layout, the claim on the
//! keys, Theta from a real chain, the batched row, and the plan's combinations check.

// The test keeps the source's names (`S`, `A`, `B`, `L`) beside the vectors.
#![allow(non_snake_case)]

use std::collections::HashMap;
use std::rc::Rc;

use fp_core::chain::public::{Binder, PublicBytes};
use fp_core::chain::rounds::VerifierRounds;
use fp_core::chain::session::VerifierSession;
use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::hash::calls::HashCalls;
use fp_core::hash::modes::Digest;
use fp_core::iop::context::OracleNotice;
use fp_core::iop::laid::LaidBlock;
use fp_core::iop::lkp::{lkp_fault, LkpKeys};
use fp_core::iop::message::Reader;
use fp_core::iop::relation::{Codes, OracleShape, Part, Row, Statement, NONE_ID};
use fp_core::iop::rng::{
    rng_fault, rng_key_row, rng_lookup, rng_planes_at, rng_planes_places, rng_plan_fault, rng_row,
    rng_theta, rng_weights_check, RngMatrix, RngRead, RngShape, RngTheta, RngWeights,
};
use fp_core::iop::tensor::Tensor;
use fp_core::numbers::codes::ceil_log2;
use fp_core::numbers::plan::{Cause, PlanRound, Planned};
use fp_core::numbers::round_names::R_RNG;
use fp_core::numbers::setting::{RoundKind, Setting};

const VECTORS: &str = include_str!("../../fixtures/rng_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.trim_start_matches('=').split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([
        F(u64::from_str_radix(p[0], 16).unwrap()),
        F(u64::from_str_radix(p[1], 16).unwrap()),
        F(u64::from_str_radix(p[2], 16).unwrap()),
    ])
}

fn e_of(x: u64) -> E {
    E([F(x), F(x + 1), F(x + 2)])
}

fn digest(s: &str) -> Digest {
    assert_eq!(s.len(), 64, "digest {}", s);
    let mut d = Digest::zero();
    for i in 0..8 {
        d.w[i] = u32::from_str_radix(&s[8 * i..8 * i + 8], 16).unwrap();
    }
    d
}

fn hex_bytes(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn kind(n: u32) -> RoundKind {
    match n {
        1 => RoundKind::Algebraic,
        2 => RoundKind::Epsilon,
        3 => RoundKind::Seed,
        4 => RoundKind::Positions,
        5 => RoundKind::Bits,
        6 => RoundKind::Seal,
        7 => RoundKind::Record,
        _ => RoundKind::Empty,
    }
}

fn lb(
    first_i: u64,
    first_c: u64,
    first_row: u64,
    first_place: u64,
    bits_i: u32,
    bits_c: u32,
    row_bits: u32,
    place_bits: u32,
    i_is_low: bool,
) -> LaidBlock {
    LaidBlock {
        first_i,
        first_c,
        first_row,
        first_place,
        bits_i,
        bits_c,
        row_bits,
        place_bits,
        i_is_low,
    }
}

fn codes() -> Codes {
    let mut codes = Codes::default();
    codes.base.push(Code { log_n: 2, ell: 2, r: 1 });
    codes.base.push(Code { log_n: 3, ell: 4, r: 2 });
    codes.base.push(Code { log_n: 5, ell: 16, r: 2 });
    codes.base.push(Code { log_n: 6, ell: 32, r: 2 });
    codes.mask.push(Code { log_n: 2, ell: 2, r: 1 });
    codes
}

fn oracle(name: &str, code: u32, main_rows: u64, answers: u32) -> OracleNotice {
    OracleNotice {
        shape: OracleShape {
            name: name.into(),
            code,
            main_rows: main_rows as usize,
            main_deg: 1,
            mask_rows: 0,
            mask_code: 0,
            answers,
        },
        leaf_class: 0,
    }
}

/// Shape A of the vector tool: N = Np = 2, one 2x2 matrix, one read of length 1, digits with
/// 4 rows and 2 columns, multiplicities with four live planes and no padding.
fn shape_a() -> RngShape {
    let mut A = RngShape::default();
    A.lanes = 2;
    A.log_radix = 3;
    A.digit_bits = [1, 1];
    A.combinations = 2;
    A.matrices = vec![RngMatrix {
        rows: 2,
        columns: 2,
        packed: 0,
        laid: vec![lb(0, 0, 0, 0, 0, 1, 0, 1, true)],
    }];
    A.reads = vec![RngRead { matrix: 0, length: 1 }];
    A.reads_in = 1;
    A.reads_laid = vec![lb(0, 0, 0, 0, 0, 1, 0, 1, true)];
    A.digit_columns = 2;
    A.digits = oracle("digits", 1, 4, 0);
    A.digits_laid = vec![lb(0, 0, 0, 0, 1, 2, 1, 2, true)];
    A.multiplicities = oracle("multiplicities", 2, 1, 0);
    A.digits_in = 3;
    A.masks_from = 2;
    A
}

/// Shape B: N = 3, Np = 4, so the lookup has five planes and two runs of padding; the digits'
/// third row has a block of its own.
fn shape_b() -> RngShape {
    let mut B = shape_a();
    B.combinations = 3;
    B.multiplicities.shape.code = 3;
    B.digits_laid = vec![
        lb(0, 0, 0, 0, 1, 2, 1, 2, true),
        lb(2, 0, 2, 0, 0, 2, 0, 2, true),
    ];
    B
}

fn statement(codes: &Codes, S: &RngShape) -> Statement {
    let mut st = Statement::new(codes.clone());
    st.sent(OracleShape {
        name: "packed".into(),
        code: 0,
        main_rows: S.packed_rows(0) as usize,
        main_deg: 1,
        mask_rows: 0,
        mask_code: 0,
        answers: 0,
    });
    st.sent(OracleShape {
        name: "reads".into(),
        code: 1,
        main_rows: 1,
        main_deg: 1,
        mask_rows: 0,
        mask_code: 0,
        answers: 0,
    });
    st.sent(OracleShape {
        name: "masks".into(),
        code: 0,
        main_rows: 1,
        main_deg: 1,
        mask_rows: 0,
        mask_code: 0,
        answers: 0,
    });
    st.sent(S.digits.shape.clone());
    st.sent(S.multiplicities.shape.clone());
    st
}

/// The shape a fault case of the vector tool builds from A.
fn fault_shape(name: &str, a: &RngShape) -> RngShape {
    let mut x = a.clone();
    match name {
        "lanes0" => x.lanes = 0,
        "lanes65" => x.lanes = 65,
        "log_radix64" => x.log_radix = 64,
        "bit0_zero" => x.digit_bits[0] = 0,
        "bit1_zero" => x.digit_bits[1] = 0,
        "window_too_big" => x.digit_bits[0] = 2,
        "wrap" => x.log_radix = 60,
        "combinations0" => x.combinations = 0,
        "no_matrix" => x.matrices.clear(),
        "rows0" => x.matrices[0].rows = 0,
        "columns0" => x.matrices[0].columns = 0,
        "rows_most" => x.matrices[0].rows = (1u64 << 24) + 1,
        "columns_most" => x.matrices[0].columns = (1u64 << 24) + 1,
        "combinations_most" => x.combinations = (1u32 << 24) + 1,
        "digit_columns_not_pow2" => x.digit_columns = 3,
        "digit_columns_small" => x.digit_columns = 1,
        "packed_is_reads" => x.matrices[0].packed = x.reads_in,
        "read_matrix" => x.reads[0].matrix = 1,
        "read_length" => x.reads[0].length = 3,
        "read_length0" => x.reads[0].length = 0,
        "digits_none" => x.digits_in = NONE_ID,
        "masks_none" => x.masks_from = NONE_ID,
        "masks_after" => x.masks_from = x.digits_in,
        "packed_after" => x.matrices[0].packed = x.digits_in,
        "reads_after" => x.reads_in = x.digits_in,
        "good_no_reads" | "good_no_reads_after" => {
            x.reads.clear();
            x.reads_laid.clear();
            x.reads_in = if name == "good_no_reads" { NONE_ID } else { x.digits_in };
        }
        _ => panic!("unknown fault case {}", name),
    }
    x
}

fn check_lookup(lines: &mut std::str::Lines, tag: &str, S: &RngShape) {
    let L = rng_lookup(S);
    let line = lines.next().unwrap();
    assert!(line.starts_with(&format!("LOOKUP {} ", tag)), "{}", line);
    let kv = fields(line);
    let joined = |xs: &[String]| xs.join(",");
    let parts: Vec<String> = L.parts.iter().map(|x| x.to_string()).collect();
    assert_eq!(kv["parts"], joined(&parts), "LOOKUP {} parts", tag);
    assert_eq!(kv["d"], L.d.to_string(), "LOOKUP {} d", tag);
    assert_eq!(kv["mu"], L.mu.to_string(), "LOOKUP {} mu", tag);
    assert_eq!(kv["live"], L.live.to_string(), "LOOKUP {} live", tag);
    assert_eq!(kv["g"], L.g.to_string(), "LOOKUP {} g", tag);
    assert_eq!(kv["shifted"], (L.shifted as u8).to_string(), "LOOKUP {} shifted", tag);
    assert_eq!(kv["planes"], L.planes().to_string(), "LOOKUP {} planes", tag);
    assert_eq!(kv["all_keys"], L.all_keys().to_string(), "LOOKUP {} all_keys", tag);
    let read_from: Vec<String> = L.read_from.iter().map(|x| x.to_string()).collect();
    assert_eq!(kv["read_from"], joined(&read_from), "LOOKUP {} read_from", tag);

    for b in &L.keys {
        let line = lines.next().unwrap();
        assert!(line.starts_with(&format!("KEY {} ", tag)), "{}", line);
        let kv = fields(line);
        assert_eq!(kv["first"], b.first.to_string(), "KEY {} first", tag);
        assert_eq!(kv["log_trees"], b.log_trees.to_string(), "KEY {} log_trees", tag);
        assert_eq!(kv["function"], b.function.to_string(), "KEY {} function", tag);
        assert_eq!(kv["padding_row"], b.padding_row.to_string(), "KEY {} padding_row", tag);
    }
    for t in &L.tables {
        let line = lines.next().unwrap();
        assert!(line.starts_with(&format!("TABLE {} ", tag)), "{}", line);
        let kv = fields(line);
        assert_eq!(kv["first"], t.first.to_string(), "TABLE {} first", tag);
        assert_eq!(kv["log_rows"], t.log_rows.to_string(), "TABLE {} log_rows", tag);
        assert_eq!(kv["function"], t.function.to_string(), "TABLE {} function", tag);
        assert_eq!(kv["rows"], t.rows.len().to_string(), "TABLE {} rows", tag);
    }
    for p in &L.padding {
        let line = lines.next().unwrap();
        assert!(line.starts_with(&format!("PADDING {} ", tag)), "{}", line);
        let kv = fields(line);
        assert_eq!(kv["part"], p.part.to_string(), "PADDING {} part", tag);
        assert_eq!(kv["first"], p.first.to_string(), "PADDING {} first", tag);
        assert_eq!(kv["log_step"], p.log_step.to_string(), "PADDING {} log_step", tag);
        assert_eq!(kv["length"], p.length.to_string(), "PADDING {} length", tag);
        assert_eq!(kv["row"], p.row.to_string(), "PADDING {} row", tag);
    }
    let line = lines.next().unwrap();
    assert!(line.starts_with(&format!("PLACES {} ", tag)), "{}", line);
    let got = line.strip_prefix(&format!("PLACES {} ", tag)).unwrap();
    assert_eq!(got, rng_planes_places(&L).to_string(), "PLACES {}", tag);
    let line = lines.next().unwrap();
    assert!(line.starts_with(&format!("LOOKUP_FAULT {} ", tag)), "{}", line);
    let got = line.strip_prefix(&format!("LOOKUP_FAULT {} ", tag)).unwrap();
    assert_eq!(got, lkp_fault(&L).unwrap_or("ok"), "LOOKUP_FAULT {}", tag);
}

fn check_planes_at(lines: &mut std::str::Lines, tag: &str, st: &Statement, S: &RngShape) {
    let L = rng_lookup(S);
    let line = lines.next().unwrap();
    let toks: Vec<&str> = line.split_whitespace().collect();
    assert_eq!(toks[0], "PLANES_AT");
    assert_eq!(toks[1], tag);
    let entries: u64 = toks[2].strip_prefix("entries=").unwrap().parse().unwrap();
    let places: u64 = toks[3].strip_prefix("places=").unwrap().parse().unwrap();
    assert_eq!(places, rng_planes_places(&L), "PLANES_AT {} places", tag);
    let o = S.digits_in + 1;
    assert_eq!(entries, 1u64 << st.table_bits(o, Part::Main), "PLANES_AT {} entries", tag);
    assert_eq!(toks.len() as u64, 4 + entries, "PLANES_AT {} values", tag);
    let mut point = Vec::new();
    for i in 0..(L.mu + L.d) as u64 {
        point.push(e_of(700 + i));
    }
    let v = Tensor::eq(&point, point.len() as u32, E::one());
    let mut row = Row::default();
    rng_planes_at(st, S, &L)(&mut row, v);
    for (j, tok) in toks[4..].iter().enumerate() {
        assert_eq!(
            row.coefficient(o, Part::Main, j as u64),
            e(tok),
            "PLANES_AT {} entry {}",
            tag,
            j
        );
    }
}

fn check_key_row(lines: &mut std::str::Lines, tag: &str, st: &Statement, S: &RngShape) {
    let bits_j = ceil_log2(S.digit_columns);
    let bits_u = ceil_log2(S.step());
    let mut k = LkpKeys::default();
    for i in 0..(1 + bits_j + bits_u) as u64 {
        k.point.push(e_of(800 + i));
    }
    k.weights.add(Tensor::eq(&k.point, k.point.len() as u32, E::one()));
    k.target = e_of(900);
    let row = rng_key_row(st, S, k);

    let line = lines.next().unwrap();
    let rest = line.strip_prefix(&format!("KEY_ROW {} row=", tag)).unwrap_or_else(|| panic!("{}", line));
    let (name, target) = rest.split_once(" target=").unwrap();
    assert_eq!(name, row.name, "KEY_ROW {} name", tag);
    assert_eq!(e(target), row.target, "KEY_ROW {} target", tag);

    let line = lines.next().unwrap();
    let toks: Vec<&str> = line.split_whitespace().collect();
    assert_eq!(toks[0], "KEY_ROW_MAIN");
    assert_eq!(toks[1], tag);
    let o = S.digits_in;
    assert_eq!(
        toks.len() as u64,
        2 + (1u64 << st.table_bits(o, Part::Main)),
        "KEY_ROW_MAIN {} values",
        tag
    );
    for (j, tok) in toks[2..].iter().enumerate() {
        assert_eq!(
            row.coefficient(o, Part::Main, j as u64),
            e(tok),
            "KEY_ROW_MAIN {} entry {}",
            tag,
            j
        );
    }
}

fn check_row(lines: &mut std::str::Lines, tag: &str, st: &Statement, S: &RngShape) {
    let phi: RngWeights = vec![vec![e_of(11)]];
    let theta: RngTheta = (0..(S.all_columns() * S.combinations as u64))
        .map(|i| (i % 3) as i8 - 1)
        .collect();
    let x = e_of(13);
    let row = rng_row(st, S, &phi, &theta, S.digits_in, &x, 3);

    let line = lines.next().unwrap();
    let rest = line.strip_prefix(&format!("ROW {} row=", tag)).unwrap_or_else(|| panic!("{}", line));
    let (name, target) = rest.split_once(" target=").unwrap();
    assert_eq!(name, row.name, "ROW {} name", tag);
    assert_eq!(e(target), row.target, "ROW {} target", tag);

    let line = lines.next().unwrap();
    assert!(line.starts_with(&format!("ROW_NUMBERS {} ", tag)), "{}", line);
    let kv = fields(line);
    assert_eq!(kv["equations"], S.equations().to_string(), "ROW_NUMBERS {} equations", tag);
    assert_eq!(kv["step"], S.step().to_string(), "ROW_NUMBERS {} step", tag);
    assert_eq!(kv["cell_rows"], S.cell_rows().to_string(), "ROW_NUMBERS {} cell_rows", tag);
    assert_eq!(kv["all_columns"], S.all_columns().to_string(), "ROW_NUMBERS {} all_columns", tag);
    assert_eq!(
        kv["read_first"],
        S.read_first(S.reads.len()).to_string(),
        "ROW_NUMBERS {} read_first",
        tag
    );

    for (label, o) in [("ROW_PACKED", 0u32), ("ROW_READS", 1u32), ("ROW_DIGITS", S.digits_in)] {
        let line = lines.next().unwrap();
        let toks: Vec<&str> = line.split_whitespace().collect();
        assert_eq!(toks[0], label, "{} {} label", label, tag);
        assert_eq!(toks[1], tag);
        assert_eq!(
            toks.len() as u64,
            2 + (1u64 << st.table_bits(o, Part::Main)),
            "{} {} values",
            label,
            tag
        );
        for (j, tok) in toks[2..].iter().enumerate() {
            assert_eq!(
                row.coefficient(o, Part::Main, j as u64),
                e(tok),
                "{} {} entry {}",
                label,
                tag,
                j
            );
        }
    }
}

fn planned_with(rounds: &[(&str, u64)]) -> Planned {
    let mut p = Planned::default();
    p.rounds = rounds
        .iter()
        .map(|(name, combinations)| {
            let mut r = PlanRound::default();
            r.name = (*name).to_string();
            r.combinations = *combinations;
            r
        })
        .collect();
    p
}

fn plan_from(kv: &HashMap<&str, &str>, rounds: &[PlanRound]) -> Planned {
    let mut set = Setting::goldilocks();
    set.salt_bytes = kv["salt"].parse().unwrap();
    set.nonce_bytes = kv["nonce"].parse().unwrap();
    set.position_bytes = kv["position"].parse().unwrap();
    set.samples = kv["samples"].parse().unwrap();
    set.saved_coefficient = kv["saved"] == "1";
    set.target = kv["target"].parse().unwrap();
    Planned {
        set,
        rounds: rounds.to_vec(),
        messages: Vec::new(),
        parts: Vec::new(),
        cause: Cause::None,
        why_not: String::new(),
    }
}

#[test]
fn rng_vectors_match_the_cpp_reference() {
    let A = shape_a();
    let B = shape_b();
    assert_eq!(rng_fault(&A), None);
    assert_eq!(rng_fault(&B), None);
    let mut lines = VECTORS.lines();

    // ---- rng_fault: every case, against the message the C++ tool printed ----
    loop {
        let line = lines.next().unwrap();
        if !line.starts_with("FAULT ") {
            // The last fault line is followed by PUBLIC_FAULT; put it back below.
            assert!(line.starts_with("PUBLIC_FAULT "), "{}", line);
            let rest = line.strip_prefix("PUBLIC_FAULT good_a ").unwrap();
            assert_eq!(A.public_fault().unwrap_or("ok"), rest);
            break;
        }
        let rest = line.strip_prefix("FAULT ").unwrap();
        let (name, want) = rest.split_once(' ').unwrap();
        let x = match name {
            "good_a" => A.clone(),
            "good_b" => B.clone(),
            _ => fault_shape(name, &A),
        };
        assert_eq!(rng_fault(&x).unwrap_or("ok"), want, "FAULT {}", name);
    }

    // ---- the lookup's public inputs ----
    check_lookup(&mut lines, "a", &A);
    check_lookup(&mut lines, "b", &B);

    // ---- the statements that the layout and row vectors use ----
    let codes = codes();
    let st_a = statement(&codes, &A);
    let st_b = statement(&codes, &B);

    check_planes_at(&mut lines, "a", &st_a, &A);
    check_planes_at(&mut lines, "b", &st_b, &B);
    check_key_row(&mut lines, "a", &st_a, &A);
    check_key_row(&mut lines, "b", &st_b, &B);
    check_row(&mut lines, "a", &st_a, &A);
    check_row(&mut lines, "b", &st_b, &B);

    // ---- rng_weights_check ----
    {
        let line = lines.next().unwrap();
        assert_eq!(line, "WEIGHTS a ok");
        rng_weights_check(&A, &vec![vec![e_of(11)]]);
    }

    // ---- rng_plan_fault ----
    {
        let pa = planned_with(&[(R_RNG, 2)]);
        let pb = planned_with(&[(R_RNG, 3)]);
        let pc = planned_with(&[("other", 2)]);
        for (name, p) in [("matching", &pa), ("another_combinations", &pb), ("no_rng_round", &pc)] {
            let line = lines.next().unwrap();
            let rest = line.strip_prefix(&format!("PLAN_FAULT {} ", name)).unwrap_or_else(|| panic!("{}", line));
            assert_eq!(rng_plan_fault(&A, p).unwrap_or("ok"), rest, "PLAN_FAULT {}", name);
        }
    }

    // ---- the chain: a hand-built plan, the C++ proof, and the two sides' Theta ----
    let line = lines.next().unwrap();
    let kv = fields(line);
    assert_eq!(line.split_whitespace().next().unwrap(), "PLAN");
    let holds: u32 = kv["holds"].parse().unwrap();
    let round_count: usize = kv["rounds"].parse().unwrap();

    let line = lines.next().unwrap();
    let set_kv = fields(line);
    assert_eq!(line.split_whitespace().next().unwrap(), "SET");

    let mut rounds: Vec<PlanRound> = Vec::new();
    let bind_line: &str;
    loop {
        let line = lines.next().unwrap();
        if !line.starts_with("ROUND ") {
            assert!(line.starts_with("BIND "), "{}", line);
            bind_line = line;
            break;
        }
        let kv = fields(line);
        let mut r = PlanRound::default();
        r.name = kv["name"].to_string();
        r.kind = kind(kv["kind"].parse().unwrap());
        r.work_bits = kv["work"].parse().unwrap();
        r.message_bytes = kv["msg"].parse().unwrap();
        r.roots = kv["roots"].parse().unwrap();
        r.answers = kv["answers"].parse().unwrap();
        r.draw_e = kv["draw_e"].parse().unwrap();
        r.draw_nonzero = kv["nz"].parse().unwrap();
        r.draw_positions = kv["draw_pos"].parse().unwrap();
        r.log_n = kv["log_n"].parse().unwrap();
        r.draw_trits = kv["trits"].parse().unwrap();
        r.rows = kv["rows"].parse().unwrap();
        r.first_list = kv["first_list"].parse().unwrap();
        r.combinations = kv["combos"].parse().unwrap();
        r.sharing = kv["sharing"].parse().unwrap();
        rounds.push(r);
    }
    let p = Rc::new(plan_from(&set_kv, &rounds));
    assert_eq!(p.holds() as u32, holds, "PLAN holds");
    assert_eq!(p.rounds.len(), round_count, "PLAN rounds");

    // BIND: the configuration digest that the C++ Binder was given.
    let kv = fields(bind_line);
    assert_eq!(bind_line.split_whitespace().next().unwrap(), "BIND");
    assert_eq!(kv["label"], "7");
    let mut config = Digest::zero();
    config.w[0] = 0xC0F1;
    assert_eq!(digest(kv["config"]), config, "BIND config");

    // SALT: the prover's salt, which the verifier reads back from the proof.
    let line = lines.next().unwrap();
    assert_eq!(line.split_whitespace().next().unwrap(), "SALT");
    let salt = digest(line.split_whitespace().nth(1).unwrap());

    let line = lines.next().unwrap();
    let theta_prover = theta_line(&line, "THETA");
    let line = lines.next().unwrap();
    assert_eq!(line, "SEAL_PROVER ok=1");

    let line = lines.next().unwrap();
    assert_eq!(line.split_whitespace().next().unwrap(), "PROOF");
    let proof = hex_bytes(line.split_whitespace().nth(1).unwrap());
    assert_eq!(&proof[..], &salt.to_bytes()[..], "PROOF is the salt");

    let line = lines.next().unwrap();
    let theta_verifier = theta_line(&line, "VTHETA");
    assert_eq!(theta_prover, theta_verifier, "THETA and VTHETA");

    let line = lines.next().unwrap();
    assert_eq!(line, "SEAL_VERIFIER ok=1 finish=1");
    assert!(lines.next().is_none());

    // The verifier's channel over the same proof.
    let mut b = Binder::new(7, p.clone());
    b.configuration(&config);
    b.parameter("a", 42u64);
    b.statement("claim", 7u64);
    let mut r = Reader::new(&proof);
    let mut session = VerifierSession::new();
    let mut calls = HashCalls::new();
    {
        let mut ch = VerifierRounds::new(&mut b, &mut r, &mut session, &mut calls);
        assert!(ch.ok());
        let theta = rng_theta(&mut ch, &A, &mut calls);
        assert_eq!(theta, theta_verifier, "VTHETA");
        ch.close_empty("last", &mut calls);
        let (ok, _sealed) = ch.seal("seal", &mut calls);
        let fin = ch.finish();
        assert!(ok, "SEAL_VERIFIER seal");
        assert!(fin, "SEAL_VERIFIER finish");
    }
    assert!(session.accepted(), "SEAL_VERIFIER accepted");
}

fn theta_line(line: &str, label: &str) -> RngTheta {
    let toks: Vec<&str> = line.split_whitespace().collect();
    assert_eq!(toks[0], label);
    let n: usize = toks[1].strip_prefix("n=").unwrap().parse().unwrap();
    let v = toks[2].strip_prefix("v=").unwrap();
    let theta: Vec<i8> = v.split(',').map(|x| x.parse().unwrap()).collect();
    assert_eq!(theta.len(), n, "{} n", label);
    theta
}
